UPDATE drug_inventory
SET current_stock = current_stock - #{quantity},
    version = version + 1,
    last_stockout_time = NOW(),
    update_time = NOW()
WHERE drug_id = #{drugId}
  AND current_stock >= #{quantity}
  AND version = #{version}

UPDATE drug_inventory
SET min_threshold = #{minThreshold}, update_time = NOW()
WHERE drug_id = #{drugId}
